theorem Nat.floor_div_eq_of_mem_Ico {h : α} (hh : 0 < h) {a : α}
    {n : ℕ} {t : α} (ht : t ∈ Ico (a + n * h) (a + (n + 1) * h)) :
    ⌊(t - a) / h⌋₊ = n

theorem piecewiseConst_eq_on_Ico {E : Type*} {c : ℕ → E} {h : α} {a : α}
    (hh : 0 < h) {n : ℕ} {t : α}
    (ht : t ∈ Ico (a + n * h) (a + (n + 1) * h)) :
    piecewiseConst c h a t = c n

theorem piecewiseLinear_eq_on_Ico (hh : 0 < h) {n : ℕ} {t : ℝ}
    (ht : t ∈ Ico (a + n * h) (a + (n + 1) * h)) :
    piecewiseLinear y c h a t = y n + (t - (a + n * h)) • c n

private lemma routeCost_eq_indicator (f : R → ℝ) (r : R) :
    P.routeCost f r
      = ∑ ℓ, if ℓ ∈ P.route r then P.linkCost ℓ (P.linkFlow f ℓ) else 0

theorem wardrop_link_unique (hinc : P.Increasing) {f g : R → ℝ}
    (hf : P.IsWardrop f) (hg : P.IsWardrop g) (ℓ : L) :
    P.linkFlow f ℓ = P.linkFlow g ℓ

theorem wardrop_linkCost_unique (hmono : ∀ ℓ, Monotone (P.linkCost ℓ)) {f g : R → ℝ}
    (hf : P.IsWardrop f) (hg : P.IsWardrop g) (ℓ : L) :
    P.linkCost ℓ (P.linkFlow f ℓ) = P.linkCost ℓ (P.linkFlow g ℓ)

theorem phiBar_bulk {K c : ℝ} {r b : ℕ}
    (h1 : ¬ (r : ℝ) + c * Real.sqrt r - b ≤ 0) (h2 : ¬ (r : ℝ) ≤ b) :
    phiBar K c r b = ((r : ℝ) - b) + (c ^ 2 / K) * Real.sqrt r

theorem phiBar_layer {K c : ℝ} {r b : ℕ}
    (h1 : ¬ (r : ℝ) + c * Real.sqrt r - b ≤ 0) (h2 : (r : ℝ) ≤ b) :
    phiBar K c r b = ((r : ℝ) + c * Real.sqrt r - b) ^ 2 / (K * Real.sqrt r)

private lemma equilibriumMaxwellian_exp_lower_bound (ρ T : ℝ) (hρ : 0 < ρ) (hT : 0 < T) :
    ∃ (C : ℝ) (K : ℕ), ∀ v : Fin 3 → ℝ,
    Real.exp (-C * (1 + ‖v‖) ^ (K : ℕ)) ≤ equilibriumMaxwellian ρ T v

private lemma integrable_mul_torusGradX (φ ψ : Torus3 → ℝ) (i : Fin 3)
    (hφ : ContDiff ℝ 1 (periodicLift φ)) (hψ : ContDiff ℝ 1 (periodicLift ψ)) :
    Integrable (fun x => φ x * torusGradX ψ x i)

private lemma hasFDerivAt_proj_mul_const (j : Fin 3) (c : ℝ) (v : Fin 3 → ℝ) :
    HasFDerivAt (fun w : Fin 3 → ℝ => w j * c)
      (c • (ContinuousLinearMap.proj j : (Fin 3 → ℝ) →L[ℝ] ℝ)) v

theorem landauMatrix_posSemidef {Ψ : ℝ → ℝ} {z : Fin 3 → ℝ}
    (hΨ : 0 ≤ Ψ (eucNorm z)) (Y : Fin 3 → ℝ) :
    0 ≤ dotProduct Y (mulVec (landauMatrix Ψ z) Y)

lemma UniformSchwartzDecay.integrable {f : Torus3 → (Fin 3 → ℝ) → ℝ}
    (hS : UniformSchwartzDecay f) (hf_smooth : ∀ x, ContDiff ℝ 3 (f x))
    (x : Torus3) : Integrable (f x)

lemma integrable_of_schwartz_bound
    {α : Type*} [MeasureSpace α] [SeminormedAddCommGroup α]
    {φ : α → ℝ}
    (hφ : ∀ k : ℕ, Integrable (fun v => ‖v‖ ^ k * |φ v|))
    {g : α → ℝ}
    (hg_meas : AEStronglyMeasurable g)
    {C : ℝ} (_ : 0 ≤ C) {K : ℕ}
    (hbound : ∀ v, ‖g v‖ ≤ C * (1 + ‖v‖) ^ K * |φ v|) :
    Integrable g

lemma score_bound_of_grad_bound
    {f : (Fin 3 → ℝ) → ℝ}
    (hf_pos : ∀ v, 0 < f v) (hf_smooth : ContDiff ℝ 3 f)
    {Cg : ℝ} {Kg : ℕ}
    (hGrad : ∀ v i, |fderiv ℝ f v (Pi.single i 1)| ≤ Cg * (1 + ‖v‖) ^ Kg * f v) :
    ∀ u i, |vGrad (Real.log ∘ f) u i| ≤ Cg * (1 + ‖u‖) ^ Kg
